# HD44780 over a PCF8574 backpack (P0 RS, P1 RW, P2 E, P3 backlight, P4-P7 D4-D7), 4-bit mode
import time


class I2cLcd:
    def __init__(self, i2c, addr, rows, cols):
        self.i2c = i2c
        self.addr = addr
        self.rows = rows
        self.cols = cols
        self.bl = 0x08
        time.sleep_ms(50)
        for _ in range(3):
            self._nib(0x03, 0)
            time.sleep_ms(5)
        self._nib(0x02, 0)
        self.cmd(0x28)  # 4-bit, 2 lines, 5x8
        self.cmd(0x08)  # display off
        self.clear()
        self.cmd(0x06)  # entry: increment
        self.cmd(0x0C)  # display on, cursor off

    def _w(self, b):
        self.i2c.writeto(self.addr, bytes([b | self.bl]))

    def _nib(self, n, rs):
        b = (n << 4) | rs
        self._w(b | 0x04)
        self._w(b)

    def _byte(self, v, rs):
        self._nib(v >> 4, rs)
        self._nib(v & 0x0F, rs)

    def cmd(self, c):
        self._byte(c, 0)
        if c <= 3:
            time.sleep_ms(2)

    def clear(self):
        self.cmd(0x01)

    def move_to(self, col, row):
        base = (0x00, 0x40, self.cols, 0x40 + self.cols)[row]
        self.cmd(0x80 | (base + col))

    def putstr(self, s):
        for ch in s:
            self._byte(ord(ch), 1)
